### CoderSudocodeHubProvider

```typescript
// src/providers/coder/sudocode-hub.ts

import { Provider, DeployOptions, Deployment, /* ... */ } from '../../types.js';
import type { CoderSudocodeHubConfig, CoderSudocodeHubDeployOptions } from '../../types.js';

/**
 * Sudocode-hub Coder provider
 * Routes requests to sudocode-hub API, which manages Coder server and credentials
 */
export class CoderSudocodeHubProvider implements Provider {
  readonly type = 'coder-sudocode-hub' as const;
  private hubUrl: string;
  private authToken: string;

  constructor(private config: CoderSudocodeHubConfig) {
    this.hubUrl = config.url;  // Hub API URL (not Coder URL directly)
    this.authToken = config.authToken;
  }

  async deploy(options: DeployOptions): Promise<Deployment> {
    // Call sudocode-hub API (NOT Tier 2 directly)
    // Hub provides githubToken and secrets from user's account
    const response = await fetch(`${this.hubUrl}/api/deployments`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.authToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        git: options.git,
        server: options.server,
        deployment: options.deployment,
        template: options.template || 'sudocode-workspace-v0',
        agents: options.agents || ['claude'],
        sudocodeVersion: options.sudocodeVersion || 'latest',
      })
    });

    if (!response.ok) {
      throw new Error(`Hub deployment failed: ${response.statusText}`);
    }

    const deployment = await response.json();
    return deployment;
  }

  async stop(name: string): Promise<void> {
    const response = await fetch(`${this.hubUrl}/api/deployments/${name}`, {
      method: 'DELETE',
      headers: {
        'Authorization': `Bearer ${this.authToken}`
      }
    });

    if (!response.ok) {
      throw new Error(`Hub deletion failed: ${response.statusText}`);
    }
  }

  async getStatus(name: string): Promise<DeploymentStatus> {
    const response = await fetch(`${this.hubUrl}/api/deployments/${name}/status`, {
      headers: {
        'Authorization': `Bearer ${this.authToken}`
      }
    });

    if (!response.ok) {
      throw new Error(`Hub status check failed: ${response.statusText}`);
    }

    const { status } = await response.json();
    return status;
  }

  async list(filters?: ListFilters): Promise<Deployment[]> {
    const response = await fetch(`${this.hubUrl}/api/deployments`, {
      headers: {
        'Authorization': `Bearer ${this.authToken}`
      }
    });

    if (!response.ok) {
      throw new Error(`Hub list failed: ${response.statusText}`);
    }

    const deployments = await response.json();
    return deployments;
  }

  async getUrls(name: string): Promise<DeploymentUrls> {
    const response = await fetch(`${this.hubUrl}/api/deployments/${name}/urls`, {
      headers: {
        'Authorization': `Bearer ${this.authToken}`
      }
    });

    if (!response.ok) {
      throw new Error(`Hub URL retrieval failed: ${response.statusText}`);
    }

    const urls = await response.json();
    return urls;
  }
}
