## Implementation Details

### Base HTTP Client

```typescript
class CoderClient {
  private baseUrl: string;
  private authToken: string;
  private defaultOrgId: string | null = null;  // Cached

  private async request<T>(
    method: 'GET' | 'POST' | 'PUT' | 'DELETE',
    path: string,
    body?: unknown
  ): Promise<T> {
    const response = await fetch(`${this.baseUrl}${path}`, {
      method,
      headers: {
        'Coder-Session-Token': this.authToken,  // Note: Uses Coder-Session-Token header
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
      body: body ? JSON.stringify(body) : undefined,
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({}));
      throw new CoderAPIError(
        response.status, 
        error.message || response.statusText, 
        error.detail,
        error.validations
      );
    }

    // Handle empty responses (e.g., DELETE operations)
    const text = await response.text();
    if (!text) {
      return undefined as T;
    }

    return JSON.parse(text) as T;
  }
}
```

### User Creation - Password Auth

```typescript
async ensureUserWithPassword(options: CreatePasswordUserOptions): Promise<CoderUser> {
  // Check if user exists
  try {
    return await this.getUser(options.username);
  } catch (e) {
    if (!(e instanceof CoderAPIError) || !e.isNotFound()) {
      throw e;
    }
  }

  // Get organization IDs (REQUIRED in newer Coder versions)
  const organizationIds = options.organizationIds || [await this.getDefaultOrganizationId()];

  // Create user with password auth
  return this.request<CoderUser>('POST', '/api/v2/users', {
    username: options.username,
    password: options.password,
    email: options.email || `${options.username}@localhost`,
    name: options.name || options.username,
    login_type: 'password',
    organization_ids: organizationIds,
  });
}
```

### User Creation - OIDC Auth

> **Validated:** OIDC user creation via API works. See [[s-3h3r]] for experiment results.
>
> **Key findings:**
> - `organization_ids` is **required** (not optional) in newer Coder versions
> - Users are created with `status: 'dormant'` until first OIDC login
> - Duplicate creation returns 409 "User already exists"
> - After OIDC login, user sees their pre-created workspace immediately

```typescript
/**
 * Derive a valid Coder username from an email address.
 * 
 * Coder usernames must:
 * - Be lowercase
 * - Contain only alphanumeric characters and hyphens
 * - Not start or end with a hyphen
 * - Not contain consecutive hyphens
 * 
 * Example: "John.Doe+test@example.com" → "john-doe-test"
 */
deriveUsernameFromEmail(email: string): string {
  return email
    .split('@')[0]
    .toLowerCase()
    .replace(/[^a-z0-9-]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

async ensureUserWithOIDC(options: CreateOIDCUserOptions): Promise<CoderUser> {
  const username = this.deriveUsernameFromEmail(options.email);

  // Check if user exists
  try {
    return await this.getUser(username);
  } catch (e) {
    if (!(e instanceof CoderAPIError) || !e.isNotFound()) {
      throw e;
    }
  }

  // Get organization IDs (REQUIRED in newer Coder versions)
  const organizationIds = options.organizationIds || [await this.getDefaultOrganizationId()];

  // Create user with OIDC auth (no password required)
  // User will be created with status: 'dormant' until first OIDC login
  return this.request<CoderUser>('POST', '/api/v2/users', {
    username,
    email: options.email,
    name: options.name || username,
    login_type: 'oidc',
    organization_ids: organizationIds,
  });
}
```

### Organization Management

```typescript
async getOrganizations(): Promise<CoderOrganization[]> {
  return this.request<CoderOrganization[]>('GET', '/api/v2/organizations');
}

async getDefaultOrganizationId(): Promise<string> {
  if (this.defaultOrgId) {
    return this.defaultOrgId;  // Return cached value
  }

  const orgs = await this.getOrganizations();
  const defaultOrg = orgs.find((o) => o.is_default);

  if (defaultOrg) {
    this.defaultOrgId = defaultOrg.id;
    return defaultOrg.id;
  }

  if (orgs.length > 0) {
    this.defaultOrgId = orgs[0].id;
    return orgs[0].id;
  }

  throw new CoderAPIError(404, 'No organizations found');
}
```

