### Workspace Creation

```typescript
async createWorkspace(options: CreateWorkspaceOptions): Promise<CoderWorkspace> {
  // Resolve template name to ID
  const template = await this.getTemplateByName(options.templateName);

  // Generate workspace name if not provided
  const name = options.name || this.generateWorkspaceName(options.templateName);

  // Build rich parameter values from WorkspaceParameters
  const richParameterValues = this.buildRichParameterValues(options.parameters);

  return this.request<CoderWorkspace>(
    'POST',
    `/api/v2/users/${encodeURIComponent(options.owner)}/workspaces`,
    {
      name,
      template_id: template.id,
      rich_parameter_values: richParameterValues,
    }
  );
}

private generateWorkspaceName(templateName: string): string {
  const suffix = Math.random().toString(36).substring(2, 8);
  return `${templateName}-${suffix}`;
}

private buildRichParameterValues(params: WorkspaceParameters): Array<{name: string, value: string}> {
  const values: Array<{name: string, value: string}> = [];

  // Required parameters
  values.push({ name: 'repository', value: params.repository });

  // Optional parameters - only include if provided
  if (params.git_host) values.push({ name: 'git_host', value: params.git_host });
  if (params.branch) values.push({ name: 'branch', value: params.branch });
  if (params.github_token) values.push({ name: 'github_token', value: params.github_token });
  if (params.agents) values.push({ name: 'agents', value: params.agents });
  if (params.secrets) values.push({ name: 'secrets', value: params.secrets });
  if (params.secrets_yaml) values.push({ name: 'secrets_yaml', value: params.secrets_yaml });
  if (params.sudocode_version) values.push({ name: 'sudocode_version', value: params.sudocode_version });
  if (params.machine_type) values.push({ name: 'machine_type', value: params.machine_type });
  if (params.memory_gb) values.push({ name: 'memory_gb', value: params.memory_gb });
  if (params.storage_gb) values.push({ name: 'storage_gb', value: params.storage_gb });
  if (params.idle_timeout_minutes) values.push({ name: 'idle_timeout_minutes', value: params.idle_timeout_minutes });
  if (params.max_ttl_hours) values.push({ name: 'max_ttl_hours', value: params.max_ttl_hours });

  return values;
}
