## HTTP Endpoints

### Endpoint → Provider Method Mapping

| Method | Endpoint | Provider Call | Description |
|--------|----------|---------------|-------------|
| `POST` | `/workspaces` | `provider.createWorkspace(body)` | Create workspace |
| `GET` | `/workspaces` | `provider.listWorkspaces(query)` | List workspaces |
| `GET` | `/workspaces/:id` | `provider.getWorkspace(id)` | Get workspace |
| `DELETE` | `/workspaces/:id` | `provider.deleteWorkspace(id)` | Delete workspace |
| `POST` | `/workspaces/:id/start` | `provider.startWorkspace(id)` | Start workspace |
| `POST` | `/workspaces/:id/stop` | `provider.stopWorkspace(id)` | Stop workspace |
| `POST` | `/users` | `provider.ensureUser(body)` | Ensure user exists |
| `GET` | `/health` | — | Health check |

### Route Handlers

```typescript
// src/server/routes.ts

import { Router } from 'express';
import { Provider, ProviderError } from '../types';
import { validateCreateWorkspaceRequest, validateEnsureUserRequest } from './validation';

export function createRoutes(provider: Provider): Router {
  const router = Router();

  // Health check (no auth required - handled before auth middleware)
  router.get('/health', (req, res) => {
    res.json({ ok: true, timestamp: new Date().toISOString() });
  });

  // === Workspace Endpoints ===

  router.post('/workspaces', async (req, res, next) => {
    try {
      const validatedBody = validateCreateWorkspaceRequest(req.body);
      const workspace = await provider.createWorkspace(validatedBody);
      res.status(201).json(workspace);
    } catch (error) {
      next(error);
    }
  });

  router.get('/workspaces', async (req, res, next) => {
    try {
      const filters = {
        owner: req.query.owner as string | undefined,
        status: req.query.status as string | undefined,
        limit: req.query.limit ? parseInt(req.query.limit as string, 10) : undefined,
        offset: req.query.offset ? parseInt(req.query.offset as string, 10) : undefined,
      };
      const workspaces = await provider.listWorkspaces(filters);
      res.json(workspaces);
    } catch (error) {
      next(error);
    }
  });

  router.get('/workspaces/:id', async (req, res, next) => {
    try {
      const workspace = await provider.getWorkspace(req.params.id);
      res.json(workspace);
    } catch (error) {
      next(error);
    }
  });

  router.delete('/workspaces/:id', async (req, res, next) => {
    try {
      await provider.deleteWorkspace(req.params.id);
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  });

  router.post('/workspaces/:id/start', async (req, res, next) => {
    try {
      await provider.startWorkspace(req.params.id);
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  });

  router.post('/workspaces/:id/stop', async (req, res, next) => {
    try {
      await provider.stopWorkspace(req.params.id);
      res.status(204).send();
    } catch (error) {
      next(error);
    }
  });

  // === User Endpoints ===

  router.post('/users', async (req, res, next) => {
    try {
      if (!provider.ensureUser) {
        res.status(501).json({ 
          error: 'User management not supported by this provider' 
        });
        return;
      }
      const validatedBody = validateEnsureUserRequest(req.body);
      const user = await provider.ensureUser(validatedBody);
      res.status(201).json(user);
    } catch (error) {
      next(error);
    }
  });

  return router;
}
```

## Middleware

### API Key Authentication

```typescript
// src/server/middleware/auth.ts

import { Request, Response, NextFunction } from 'express';
import { ProviderError } from '../../types';

/**
 * Middleware that validates API key from Authorization header.
 * Health check endpoint bypasses authentication.
 */
export function apiKeyAuth(validApiKeys: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    // Skip auth for health check
    if (req.path === '/health' || req.path.endsWith('/health')) {
      return next();
    }

    const authHeader = req.headers.authorization;

    if (!authHeader) {
      throw new ProviderError(
        'Missing Authorization header',
        'AUTHENTICATION_FAILED',
        401
      );
    }

    if (!authHeader.startsWith('Bearer ')) {
      throw new ProviderError(
        'Authorization header must use Bearer scheme',
        'AUTHENTICATION_FAILED',
        401
      );
    }

    const apiKey = authHeader.slice(7); // Remove "Bearer "

    if (!validApiKeys.includes(apiKey)) {
      throw new ProviderError(
        'Invalid API key',
        'AUTHENTICATION_FAILED',
        401
      );
    }

    next();
  };
}
```

### Error Handler

```typescript
// src/server/middleware/error.ts

import { Request, Response, NextFunction } from 'express';
import { ProviderError } from '../../types';

/**
 * Express error handler that maps ProviderError to HTTP responses.
 * ProviderError already carries statusCode, so we use it directly.
 */
export function errorHandler(
  error: Error,
  req: Request,
  res: Response,
  next: NextFunction
) {
  // Log error for debugging (in production, use proper logger)
  console.error(`[${req.method} ${req.path}] Error:`, error.message);

  if (error instanceof ProviderError) {
    res.status(error.statusCode).json({
      error: error.message,
      code: error.code,
    });
    return;
  }

  // Validation errors from our validation layer
  if (error.name === 'ValidationError') {
    res.status(400).json({
      error: error.message,
      code: 'INVALID_REQUEST',
    });
    return;
  }

  // Unknown errors - don't leak details
  res.status(500).json({
    error: 'Internal server error',
    code: 'INTERNAL_ERROR',
  });
}
```

## Request Validation

Validation happens before calling provider methods. Uses the rules from [[s-7gqg]].

```typescript
// src/server/validation.ts

import { CreateWorkspaceRequest, EnsureUserRequest, ProviderError } from '../types';

class ValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ValidationError';
  }
}

/**
 * Validates CreateWorkspaceRequest.
 * Throws ValidationError if invalid.
 */
export function validateCreateWorkspaceRequest(body: unknown): CreateWorkspaceRequest {
  if (!body || typeof body !== 'object') {
    throw new ValidationError('Request body must be an object');
  }

  const req = body as Record<string, unknown>;

  // Required: repository
  if (!req.repository || typeof req.repository !== 'string') {
    throw new ValidationError('repository is required and must be a string');
  }

  // Validate repository format: owner/repo
  if (!/^[\w.-]+\/[\w.-]+$/.test(req.repository)) {
    throw new ValidationError('repository must be in "owner/repo" format');
  }

  // Required: userIdentity with at least one field
  if (!req.userIdentity || typeof req.userIdentity !== 'object') {
    throw new ValidationError('userIdentity is required');
  }

  const identity = req.userIdentity as Record<string, unknown>;
  if (!identity.email && !identity.sub && !identity.username) {
    throw new ValidationError(
      'userIdentity must have at least one of: email, sub, username'
    );
  }

  // Optional numeric fields
  if (req.cpuCores !== undefined) {
    if (typeof req.cpuCores !== 'number' || req.cpuCores <= 0 || !Number.isInteger(req.cpuCores)) {
      throw new ValidationError('cpuCores must be a positive integer');
    }
  }

  if (req.memoryGb !== undefined) {
    if (typeof req.memoryGb !== 'number' || req.memoryGb <= 0) {
      throw new ValidationError('memoryGb must be a positive number');
    }
  }

  if (req.diskSizeGb !== undefined) {
    if (typeof req.diskSizeGb !== 'number' || req.diskSizeGb <= 0 || !Number.isInteger(req.diskSizeGb)) {
      throw new ValidationError('diskSizeGb must be a positive integer');
    }
  }

  if (req.idleTimeoutMinutes !== undefined) {
    if (typeof req.idleTimeoutMinutes !== 'number' || req.idleTimeoutMinutes <= 0) {
      throw new ValidationError('idleTimeoutMinutes must be a positive number');
    }
  }

  if (req.maxTtlHours !== undefined) {
    if (typeof req.maxTtlHours !== 'number' || req.maxTtlHours <= 0) {
      throw new ValidationError('maxTtlHours must be a positive number');
    }
  }

  return req as unknown as CreateWorkspaceRequest;
}

/**
 * Validates EnsureUserRequest.
 * Throws ValidationError if invalid.
 */
export function validateEnsureUserRequest(body: unknown): EnsureUserRequest {
  if (!body || typeof body !== 'object') {
    throw new ValidationError('Request body must be an object');
  }

  const req = body as Record<string, unknown>;

  // Required: email
  if (!req.email || typeof req.email !== 'string') {
    throw new ValidationError('email is required and must be a string');
  }

  // Required: loginType must be 'oidc'
  if (req.loginType !== 'oidc') {
    throw new ValidationError('loginType must be "oidc"');
  }

  return req as unknown as EnsureUserRequest;
}
```

