## Usage Example

```typescript
// coder-infra/src/main.ts

import { createServer, Provider } from 'sudopod';
import { CoderProvider } from './provider';

async function main() {
  const provider: Provider = new CoderProvider({
    coderUrl: process.env.CODER_URL!,
    adminToken: process.env.CODER_ADMIN_TOKEN!,
  });

  const server = createServer(provider, {
    apiKeys: process.env.SUDOPOD_API_KEYS!.split(','),
    basePath: '/api/v1', // optional
  });

  const port = process.env.PORT || 8080;
  server.listen(port, () => {
    console.log(`sudopod-api listening on :${port}`);
  });
}

main().catch(console.error);
