## CoderProvider Class

```typescript
// coder-infra/src/provider/index.ts

import {
  Provider,
  CreateWorkspaceRequest,
  Workspace,
  ListWorkspacesFilter,
  EnsureUserRequest,
  User,
  WorkspaceNotFoundError,
  UserNotFoundError,
} from 'sudopod';

import { CoderClient, CoderAPIError } from '../client';
import { mapWorkspaceStatus, mapUserStatus } from './status-mapper';

export interface CoderProviderConfig {
  /** Coder server URL (e.g., 'http://coder:7080') */
  coderUrl: string;

  /** Admin API token for Coder authentication */
  adminToken: string;

  /** Template name to use for workspaces (default: 'sudocode-workspace') */
  templateName?: string;
}

export class CoderProvider implements Provider {
  private client: CoderClient;
  private templateName: string;

  constructor(config: CoderProviderConfig) {
    this.client = new CoderClient({
      url: config.coderUrl,
      authToken: config.adminToken,
    });
    this.templateName = config.templateName ?? 'sudocode-workspace';
  }

  // =========================================================================
  // Workspace Lifecycle
  // =========================================================================

  async createWorkspace(req: CreateWorkspaceRequest): Promise<Workspace> {
    // 1. Ensure user exists (OIDC)
    const user = await this.ensureUserFromIdentity(req.userIdentity);

    // 2. Generate workspace name from repository
    const workspaceName = this.generateWorkspaceName(req.repository);

    // 3. Translate to Coder template parameters
    const parameters = this.buildTemplateParameters(req);

    // 4. Create workspace via Coder API
    const coderWorkspace = await this.client.createWorkspace({
      owner: user.username,
      name: workspaceName,
      templateName: this.templateName,
      parameters,
    });

    // 5. Return standardized response
    return this.mapWorkspace(coderWorkspace, user.username);
  }

  async getWorkspace(id: string): Promise<Workspace> {
    try {
      const coderWorkspace = await this.client.getWorkspace(id);
      return this.mapWorkspace(coderWorkspace, coderWorkspace.owner_name);
    } catch (error) {
      if (error instanceof CoderAPIError && error.isNotFound()) {
        throw new WorkspaceNotFoundError(id);
      }
      throw error;
    }
  }

  async deleteWorkspace(id: string): Promise<void> {
    try {
      await this.client.deleteWorkspace(id);
    } catch (error) {
      if (error instanceof CoderAPIError && error.isNotFound()) {
        throw new WorkspaceNotFoundError(id);
      }
      throw error;
    }
  }

  async listWorkspaces(filters?: ListWorkspacesFilter): Promise<Workspace[]> {
    // Coder API doesn't have a direct listWorkspaces with filters,
    // so we use getWorkspacesByOwner if owner filter is provided
    if (filters?.owner) {
      const coderWorkspaces = await this.client.getWorkspacesByOwner(filters.owner);
      return coderWorkspaces.map(ws => this.mapWorkspace(ws, ws.owner_name));
    }

    // For now, return empty array if no owner filter
    // Full listing would require admin API access with pagination
    return [];
  }

  // =========================================================================
  // Workspace State
  // =========================================================================

  async startWorkspace(id: string): Promise<void> {
    try {
      await this.client.startWorkspace(id);
    } catch (error) {
      if (error instanceof CoderAPIError && error.isNotFound()) {
        throw new WorkspaceNotFoundError(id);
      }
      throw error;
    }
  }

  async stopWorkspace(id: string): Promise<void> {
    try {
      await this.client.stopWorkspace(id);
    } catch (error) {
      if (error instanceof CoderAPIError && error.isNotFound()) {
        throw new WorkspaceNotFoundError(id);
      }
      throw error;
    }
  }

  // =========================================================================
  // User Management
  // =========================================================================

  async ensureUser(req: EnsureUserRequest): Promise<User> {
    const coderUser = await this.client.ensureUserWithOIDC({
      email: req.email,
      name: req.username,
      organizationIds: req.organizationIds,
    });

    return {
      id: coderUser.id,
      username: coderUser.username,
      email: coderUser.email,
      status: mapUserStatus(coderUser.status),
      createdAt: coderUser.created_at,
    };
  }

  // =========================================================================
  // Private Helpers
  // =========================================================================

  /**
   * Ensure user exists from UserIdentity.
   * Requires at least email for OIDC user creation.
   */
  private async ensureUserFromIdentity(identity: CreateWorkspaceRequest['userIdentity']): Promise<User> {
    if (!identity.email) {
      throw new Error('userIdentity.email is required for Coder OIDC user creation');
    }

    return this.ensureUser({
      email: identity.email,
      username: identity.username,
      loginType: 'oidc',
    });
  }

  /**
   * Generate workspace name from repository.
   * Format: {repo-name}-{random-suffix}
   */
  private generateWorkspaceName(repository: string): string {
    // Extract repo name from "owner/repo" format
    const repoName = repository.split('/').pop() ?? 'workspace';
    const suffix = Math.random().toString(36).substring(2, 8);

    // Coder workspace names must be lowercase alphanumeric with hyphens
    const sanitized = repoName
      .toLowerCase()
      .replace(/[^a-z0-9-]/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-|-$/g, '');

    return `${sanitized}-${suffix}`;
  }

  /**
   * Build Coder template parameters from CreateWorkspaceRequest.
   */
  private buildTemplateParameters(req: CreateWorkspaceRequest): Record<string, string> {
    const params: Record<string, string> = {
      repository: this.formatRepositoryUrl(req.repository),
    };

    if (req.branch) params.branch = req.branch;
    if (req.githubToken) params.github_token = req.githubToken;
    if (req.cpuCores) params.cpu_cores = String(req.cpuCores);
    if (req.memoryGb) params.memory_gb = String(req.memoryGb);
    if (req.diskSizeGb) params.storage_gb = String(req.diskSizeGb);
    if (req.idleTimeoutMinutes) params.idle_timeout_minutes = String(req.idleTimeoutMinutes);
    if (req.maxTtlHours) params.max_ttl_hours = String(req.maxTtlHours);

    if (req.secrets && Object.keys(req.secrets).length > 0) {
      params.secrets = JSON.stringify(req.secrets);
    }

    return params;
  }

  /**
   * Format repository from "owner/repo" to full HTTPS URL.
   */
  private formatRepositoryUrl(repository: string): string {
    if (repository.startsWith('http://') || repository.startsWith('https://')) {
      return repository;
    }
    // Assume GitHub if just "owner/repo"
    return `https://github.com/${repository}`;
  }

  /**
   * Map Coder workspace to standardized Workspace type.
   */
  private mapWorkspace(coderWorkspace: any, ownerUsername: string): Workspace {
    const baseUrl = this.client.baseUrl;

    return {
      id: coderWorkspace.id,
      name: coderWorkspace.name,
      status: mapWorkspaceStatus(coderWorkspace.latest_build?.status),
      urls: {
        workspace: `${baseUrl}/@${ownerUsername}/${coderWorkspace.name}`,
        ide: `${baseUrl}/@${ownerUsername}/${coderWorkspace.name}/apps/code-server`,
        terminal: `${baseUrl}/@${ownerUsername}/${coderWorkspace.name}/terminal`,
      },
      createdAt: coderWorkspace.created_at,
      owner: ownerUsername,
      repository: this.extractRepository(coderWorkspace),
      branch: this.extractBranch(coderWorkspace),
    };
  }

  /**
   * Extract repository from Coder workspace parameters.
   */
  private extractRepository(coderWorkspace: any): string | undefined {
    // Coder stores parameters in latest_build.resources[].rich_parameter_values
    // This is a simplified extraction - real implementation may need to dig deeper
    return coderWorkspace.latest_build?.rich_parameter_values?.find(
      (p: any) => p.name === 'repository'
    )?.value;
  }

  /**
   * Extract branch from Coder workspace parameters.
   */
  private extractBranch(coderWorkspace: any): string | undefined {
    return coderWorkspace.latest_build?.rich_parameter_values?.find(
      (p: any) => p.name === 'branch'
    )?.value;
  }
}
