## Status Mapper

```typescript
// coder-infra/src/provider/status-mapper.ts

import { WorkspaceStatus, UserStatus } from 'sudopod';

/**
 * Map Coder workspace build status to standardized WorkspaceStatus.
 */
export function mapWorkspaceStatus(coderStatus: string | undefined): WorkspaceStatus {
  const statusMap: Record<string, WorkspaceStatus> = {
    'pending': 'pending',
    'starting': 'starting',
    'running': 'running',
    'stopping': 'stopping',
    'stopped': 'stopped',
    'failed': 'failed',
    'canceling': 'stopping',
    'canceled': 'stopped',
    'deleting': 'deleting',
    'deleted': 'deleting',
  };

  return statusMap[coderStatus ?? ''] ?? 'failed';
}

/**
 * Map Coder user status to standardized UserStatus.
 */
export function mapUserStatus(coderStatus: string): UserStatus {
  const statusMap: Record<string, UserStatus> = {
    'active': 'active',
    'dormant': 'dormant',
    'suspended': 'suspended',
  };

  return statusMap[coderStatus] ?? 'dormant';
}
