## Connector Implementation

```typescript
// src/connectors/hub/index.ts

import type { Connector } from '../../core/connector';
import type {
  CreateWorkspaceRequest,
  Workspace,
  ListFilters,
} from '../../types';
import { HubConnectorConfig } from './types';
import { ConnectorError, AuthenticationError } from '../../core/errors';

/**
 * Connector that routes requests through sudocode-hub.
 * 
 * Hub handles:
 * - GitHub token injection (via GitHub App installation)
 * - Secret injection (from user's stored secrets)
 * - User identity injection (from OAuth session)
 * - Routing to the correct provider host
 */
export class HubConnector implements Connector {
  readonly type = 'hub' as const;

  private hubUrl: string;
  private hubToken: string;
  private provider: string;
  private timeout: number;

  constructor(config: HubConnectorConfig) {
    this.hubUrl = config.hubUrl.replace(/\/$/, ''); // Remove trailing slash
    this.hubToken = config.hubToken;
    this.provider = config.provider;
    this.timeout = config.timeout ?? 60000;
  }

  /**
   * Create a workspace through the hub.
   * Hub will inject githubToken, secrets, and userIdentity.
   */
  async createWorkspace(req: HubCreateWorkspaceRequest): Promise<Workspace> {
    // Only send fields that CLI provides - hub adds the rest
    const body = {
      repository: req.repository,
      branch: req.branch,
      cpuCores: req.cpuCores,
      memoryGb: req.memoryGb,
      diskSizeGb: req.diskSizeGb,
      idleTimeoutMinutes: req.idleTimeoutMinutes,
      maxTtlHours: req.maxTtlHours,
    };

    return this.request<Workspace>(
      'POST',
      `/api/providers/${this.provider}/workspaces`,
      body
    );
  }

  /**
   * Get workspace by ID.
   */
  async getWorkspace(id: string): Promise<Workspace> {
    return this.request<Workspace>(
      'GET',
      `/api/providers/${this.provider}/workspaces/${encodeURIComponent(id)}`
    );
  }

  /**
   * Delete workspace by ID.
   */
  async deleteWorkspace(id: string): Promise<void> {
    await this.request<void>(
      'DELETE',
      `/api/providers/${this.provider}/workspaces/${encodeURIComponent(id)}`
    );
  }

  /**
   * List workspaces for the authenticated user.
   */
  async listWorkspaces(filters?: ListFilters): Promise<Workspace[]> {
    const params = new URLSearchParams();
    if (filters?.status) params.set('status', filters.status);
    if (filters?.limit) params.set('limit', String(filters.limit));
    if (filters?.offset) params.set('offset', String(filters.offset));

    const query = params.toString();
    const path = `/api/providers/${this.provider}/workspaces${query ? `?${query}` : ''}`;

    return this.request<Workspace[]>('GET', path);
  }

  /**
   * Start a stopped workspace.
   */
  async startWorkspace(id: string): Promise<void> {
    await this.request<void>(
      'POST',
      `/api/providers/${this.provider}/workspaces/${encodeURIComponent(id)}/start`
    );
  }

  /**
   * Stop a running workspace.
   */
  async stopWorkspace(id: string): Promise<void> {
    await this.request<void>(
      'POST',
      `/api/providers/${this.provider}/workspaces/${encodeURIComponent(id)}/stop`
    );
  }

  /**
   * Check if hub is reachable and token is valid.
   */
  async validate(): Promise<void> {
    try {
      await this.request<{ ok: boolean }>('GET', '/api/health');
    } catch (error: any) {
      if (error.statusCode === 401) {
        throw new AuthenticationError(
          'hub',
          'Hub token is invalid or expired. Run: sudocode login'
        );
      }
      throw error;
    }
  }

  /**
   * Get information about the authenticated user.
   */
  async getUser(): Promise<HubUser> {
    return this.request<HubUser>('GET', '/api/user');
  }

  /**
   * Internal request handler.
   */
  private async request<T>(method: string, path: string, body?: unknown): Promise<T> {
    const url = `${this.hubUrl}${path}`;

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), this.timeout);

      const response = await fetch(url, {
        method,
        headers: {
          'Authorization': `Bearer ${this.hubToken}`,
          'Content-Type': 'application/json',
        },
        body: body ? JSON.stringify(body) : undefined,
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      // Handle no-content responses
      if (response.status === 204) {
        return undefined as T;
      }

      const data = await response.json();

      if (!response.ok) {
        throw new HubError(
          data.error || `Hub request failed with status ${response.status}`,
          data.code || 'HUB_ERROR',
          response.status
        );
      }

      return data as T;

    } catch (error: any) {
      if (error.name === 'AbortError') {
        throw new ConnectorError('hub', method, 'Request timed out');
      }
      if (error instanceof HubError) {
        throw error;
      }
      throw new ConnectorError('hub', method, error.message);
    }
  }
}

/**
 * Request type for creating workspace via hub.
 * Note: Does NOT include githubToken, secrets, or userIdentity.
 * Hub injects these from the authenticated user's session.
 */
export interface HubCreateWorkspaceRequest {
  repository: string;
  branch?: string;
  cpuCores?: number;
  memoryGb?: number;
  diskSizeGb?: number;
  idleTimeoutMinutes?: number;
  maxTtlHours?: number;
}

export interface HubUser {
  id: string;
  email: string;
  username?: string;
  providers: string[]; // Available providers for this user
}

export class HubError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number
  ) {
    super(message);
    this.name = 'HubError';
  }
}
