## Provider Factory

```typescript
/**
 * Create a provider instance.
 *
 * The provider name selects which implementation to use.
 * The config is provider-specific — TypeScript overloads enforce
 * the correct config type for each provider name.
 */
function createProvider(provider: 'codespaces', config: CodespacesConfig): Provider;
function createProvider(provider: 'coder', config: CoderConfig): Provider;
function createProvider(provider: 'hub', config: HubConfig): Provider;
function createProvider(provider: string, config: unknown): Provider {
  switch (provider) {
    case 'codespaces':
      return new CodespacesProvider(config as CodespacesConfig);
    case 'coder':
      return new CoderProvider(config as CoderConfig);
    case 'hub':
      return new HubProvider(config as HubConfig);
    default:
      throw new Error(`Unknown provider: ${provider}`);
  }
}
```

