### Watch Workspace (SSE Stream)

For polling workspace status until a desired state is reached. The SDK provides a polling helper rather than SSE streaming, since the polling approach is simpler and sufficient.

```typescript
interface WaitForBuildParams {
  workspaceId: string;
  /** Desired workspace status to wait for. */
  targetStatus: CoderWorkspaceStatus;
  /** Polling interval in ms. Default: 2000. */
  pollIntervalMs?: number;
  /** Timeout in ms. Default: 300000 (5 minutes). */
  timeoutMs?: number;
}

async waitForWorkspaceStatus(params: WaitForBuildParams): Promise<CoderWorkspace> {
  const interval = params.pollIntervalMs ?? 2000;
  const timeout = params.timeoutMs ?? 300_000;
  const deadline = Date.now() + timeout;

  while (Date.now() < deadline) {
    const workspace = await this.getWorkspace(params.workspaceId);
    if (workspace.latest_build.status === params.targetStatus) {
      return workspace;
    }
    if (workspace.latest_build.status === 'failed' || workspace.latest_build.status === 'canceled') {
      throw new CoderApiError(0, `Workspace build ${workspace.latest_build.status}`, 'POLL', `/workspaces/${params.workspaceId}`);
    }
    await sleep(interval);
  }

  throw new CoderApiError(0, `Timed out waiting for workspace status: ${params.targetStatus}`, 'POLL', `/workspaces/${params.workspaceId}`);
}
```

