## Workspace-to-Provider Mapping

Utility to convert `CoderWorkspace` → Provider `Workspace` type.

```typescript
interface MapWorkspaceOptions {
  /** Coder instance base URL, for constructing dashboard URLs */
  baseUrl: string;
}

function mapCoderWorkspaceToWorkspace(cw: CoderWorkspace, options: MapWorkspaceOptions): Workspace {
  const agents = cw.latest_build.resources.flatMap(r => r.agents ?? []);
  const connectedAgent = agents.find(a => a.status === 'connected') ?? agents[0];

  return {
    id: cw.id,
    name: cw.name,
    status: mapCoderStatusToWorkspaceStatus(cw.latest_build.status),
    repository: extractRepository(cw),
    createdAt: new Date(cw.created_at),
    lastActivityAt: cw.last_used_at ? new Date(cw.last_used_at) : undefined,
    connection: {
      ssh: {
        // Pure API — SSH command uses Coder's standard format
        command: `ssh coder.${cw.name}`,
      },
      urls: {
        dashboard: `${options.baseUrl}/@${cw.owner_name}/${cw.name}`,
      },
    },
  };
}

/**
 * Extract repository info from workspace metadata or template parameters.
 * This is template-dependent — the template must expose repository info
 * as resource metadata.
 */
function extractRepository(cw: CoderWorkspace): { owner: string; repo: string } {
  const metadata = cw.latest_build.resources
    .flatMap(r => r.metadata ?? []);

  const repoMeta = metadata.find(m => m.key === 'repository');
  if (repoMeta) {
    const [owner, repo] = repoMeta.value.split('/');
    return { owner: owner ?? '', repo: repo ?? '' };
  }

  return { owner: '', repo: '' };
}
```

